package com.paicli.state;

import java.sql.*;import java.util.*;

public final class McpToolCallStore {
 private static final Set<String> TERMINAL=Set.of("DENIED","SUCCEEDED","TOOL_ERROR","TIMED_OUT","PROTOCOL_ERROR","PROCESS_EXITED","SANITIZER_REJECTED","CANCELLED","UNKNOWN_OUTCOME");private final Connection c;public McpToolCallStore(Connection c){this.c=c;}
 public void createToolCall(CallCreate x)throws SQLException{if(x.attempt()<1)throw new IllegalArgumentException("attempt >= 1");if(!"PENDING".equals(x.approval()))throw new IllegalArgumentException("new tool calls must start with PENDING approval");validateReferences(x);try(PreparedStatement s=c.prepareStatement("INSERT INTO mcp_tool_calls(mcp_tool_call_id,session_id,catalog_id,mcp_tool_id,task_id,coding_run_id,occurrence_key,attempt_number,request_id,manifest_hash,catalog_hash,schema_hash,exposed_tool_name,original_tool_name,arguments_hash,bounded_arguments_summary,approval_decision,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'PENDING')")){int i=1;s.setString(i++,x.id());s.setString(i++,x.session());s.setString(i++,x.catalog());s.setString(i++,x.tool());s.setString(i++,x.task());s.setString(i++,x.run());s.setString(i++,x.occurrence());s.setInt(i++,x.attempt());s.setString(i++,x.requestId());s.setString(i++,x.manifestHash());s.setString(i++,x.catalogHash());s.setString(i++,x.schemaHash());s.setString(i++,x.exposedName());s.setString(i++,x.originalName());s.setString(i++,x.argumentsHash());s.setString(i++,McpStoreSupport.optional(x.argumentsSummary(),4096));s.setString(i,x.approval());s.executeUpdate();}}
 private void validateReferences(CallCreate x)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT 1 FROM mcp_sessions s JOIN mcp_server_manifests m ON m.manifest_id=s.manifest_id JOIN mcp_tool_catalogs c ON c.catalog_id=? AND c.session_id=s.session_id JOIN mcp_tools t ON t.mcp_tool_id=? AND t.catalog_id=c.catalog_id WHERE s.session_id=? AND m.config_hash=? AND c.catalog_hash=? AND t.schema_hash=? AND t.exposed_name=? AND t.original_name=? AND t.exposure_status='EXPOSED'")){s.setString(1,x.catalog());s.setString(2,x.tool());s.setString(3,x.session());s.setString(4,x.manifestHash());s.setString(5,x.catalogHash());s.setString(6,x.schemaHash());s.setString(7,x.exposedName());s.setString(8,x.originalName());try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalArgumentException("MCP call artifact hashes do not match an exposed referenced tool");}}}
 public void recordApprovalDecision(String id,String decision)throws SQLException{if(!Set.of("APPROVED","DENIED","NOT_REQUESTED").contains(decision))throw new IllegalArgumentException("invalid approval");String status=decision.equals("DENIED")?"DENIED":"PENDING";update(id,"PENDING",status,decision,null,null,false,false);}
 public void approveAndMarkRunning(String id,String requestId)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_tool_calls SET approval_decision='APPROVED',status='RUNNING',request_id=? WHERE mcp_tool_call_id=? AND status='PENDING' AND approval_decision='PENDING' AND request_id IS NULL")){s.setString(1,McpStoreSupport.text(requestId,"requestId",128));s.setString(2,id);if(s.executeUpdate()!=1)throw new SQLException("tool call not pending or request id already assigned");}}
 public void rejectValidation(String id,String error)throws SQLException{update(id,"PENDING","SANITIZER_REJECTED","NOT_REQUESTED",null,error,false,true);}
 public void markRunning(String id)throws SQLException{update(id,"PENDING","RUNNING",null,null,null,false,false);}
 public void completeSuccess(String id,String hash,boolean truncated,boolean redacted)throws SQLException{update(id,"RUNNING","SUCCEEDED",null,hash,null,truncated,redacted);}
 public void completeToolError(String id,String hash,String error)throws SQLException{update(id,"RUNNING","TOOL_ERROR",null,hash,error,false,false);}
 public void markTimedOut(String id,String error)throws SQLException{update(id,"RUNNING","TIMED_OUT",null,null,error,false,false);}
 public void markProtocolError(String id,String error)throws SQLException{update(id,"RUNNING","PROTOCOL_ERROR",null,null,error,false,false);}
 public void markProcessExited(String id,String error)throws SQLException{update(id,"RUNNING","PROCESS_EXITED",null,null,error,false,false);}
 public void markSanitizerRejected(String id,String error)throws SQLException{update(id,"RUNNING","SANITIZER_REJECTED",null,null,error,false,false);}
 public boolean cancelPendingForRecovery(String id)throws SQLException{return recoveryUpdate(id,"PENDING","CANCELLED","RECOVERY_BEFORE_DISPATCH");}
 public boolean markUnknownOutcome(String id)throws SQLException{return recoveryUpdate(id,"RUNNING","UNKNOWN_OUTCOME","UNKNOWN_EXTERNAL_OUTCOME");}
 public List<CallRecord> findResiduesBySession(String session)throws SQLException{return list("session_id=? AND status IN ('PENDING','RUNNING')",session);}
 public List<CallRecord> findRecentBySession(String session,int limit)throws SQLException{if(limit<1)throw new IllegalArgumentException("limit >= 1");try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_tool_calls WHERE session_id=? ORDER BY started_at DESC,mcp_tool_call_id DESC LIMIT ?")){s.setString(1,session);s.setInt(2,limit);List<CallRecord>x=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())x.add(map(r));}return x;}}
 private boolean recoveryUpdate(String id,String from,String to,String category)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_tool_calls SET status=?,error_category=?,bounded_error_excerpt=?,completed_at=datetime('now') WHERE mcp_tool_call_id=? AND status=?")){s.setString(1,to);s.setString(2,category);s.setString(3,category);s.setString(4,id);s.setString(5,from);return s.executeUpdate()==1;}}
 private void update(String id,String from,String to,String approval,String hash,String error,boolean trunc,boolean redact)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_tool_calls SET status=?,approval_decision=COALESCE(?,approval_decision),result_hash=?,truncated=?,redacted=?,error_category=?,bounded_error_excerpt=?,completed_at=CASE WHEN ? THEN datetime('now') ELSE completed_at END WHERE mcp_tool_call_id=? AND status=?")){s.setString(1,to);s.setString(2,approval);s.setString(3,hash);s.setInt(4,trunc?1:0);s.setInt(5,redact?1:0);s.setString(6,error);s.setString(7,McpStoreSupport.optional(error,4096));s.setBoolean(8,TERMINAL.contains(to));s.setString(9,id);s.setString(10,from);if(s.executeUpdate()!=1)throw new SQLException("tool call not found or terminal/invalid transition");}}
 public Optional<CallRecord> findById(String id)throws SQLException{return one("mcp_tool_call_id=?",id);}
 public Optional<CallRecord> findBySessionAndRequestId(String session,String request)throws SQLException{return one("session_id=? AND request_id=?",session,request);}
 public List<CallRecord> findByOccurrence(String session,String occurrence)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_tool_calls WHERE session_id=? AND occurrence_key=? ORDER BY attempt_number")){s.setString(1,session);s.setString(2,occurrence);List<CallRecord>x=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())x.add(map(r));}return x;}}
 private List<CallRecord> list(String where,String...p)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_tool_calls WHERE "+where+" ORDER BY started_at,mcp_tool_call_id")){for(int i=0;i<p.length;i++)s.setString(i+1,p[i]);List<CallRecord>x=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())x.add(map(r));}return x;}}
 private Optional<CallRecord> one(String where,String...p)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_tool_calls WHERE "+where)){for(int i=0;i<p.length;i++)s.setString(i+1,p[i]);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 private CallRecord map(ResultSet r)throws SQLException{return new CallRecord(r.getString("mcp_tool_call_id"),r.getString("session_id"),r.getString("catalog_id"),r.getString("mcp_tool_id"),r.getString("occurrence_key"),r.getInt("attempt_number"),r.getString("request_id"),r.getString("approval_decision"),r.getString("status"),r.getString("result_hash"),r.getInt("truncated")!=0,r.getInt("redacted")!=0,r.getString("error_category"),r.getString("bounded_error_excerpt"),r.getString("exposed_tool_name"),r.getString("arguments_hash"),r.getString("started_at"),r.getString("completed_at"));}
 public List<String> reportForTaskRun(String task,String run)throws SQLException {
  if(run==null)return List.of();
  try(var s=c.prepareStatement("SELECT mcp_tool_call_id,original_tool_name,status,approval_decision,occurrence_key FROM mcp_tool_calls WHERE task_id=? AND coding_run_id=? ORDER BY started_at,mcp_tool_call_id LIMIT 21")) {
   s.setString(1,task);s.setString(2,run);var lines=new ArrayList<String>();
   try(var rows=s.executeQuery()){while(rows.next()) {
    if(lines.size()==20){lines.add("MCP: additional calls omitted");break;}
    String status=rows.getString("status");
    String certainty=Set.of("RUNNING","TIMED_OUT","PROCESS_EXITED","PROTOCOL_ERROR","UNKNOWN_OUTCOME").contains(status)?"; external outcome unknown, do not replay":"";
    lines.add("MCP "+rows.getString("original_tool_name")+": "+status+"; approval="+rows.getString("approval_decision")
      +"; call="+rows.getString("mcp_tool_call_id")+"; occurrence="+rows.getString("occurrence_key")+certainty);
   }}return List.copyOf(lines);
  }
 }
 public record CallCreate(String id,String session,String catalog,String tool,String task,String run,String occurrence,int attempt,String requestId,String manifestHash,String catalogHash,String schemaHash,String exposedName,String originalName,String argumentsHash,String argumentsSummary,String approval){}
 public record CallRecord(String id,String session,String catalog,String tool,String occurrence,int attempt,String requestId,String approval,String status,String resultHash,boolean truncated,boolean redacted,String errorCategory,String errorExcerpt,String exposedName,String argumentsHash,String startedAt,String completedAt){}
}
